406:     function drawCoverImage(im, x, y, w, h, radius = 0) {
407:       ctx.save();
408:       if (radius > 0) {
409:         ctx.beginPath();
410:         ctx.roundRect(x, y, w, h, radius);
411:         ctx.clip();
412:       }
413:       if (im) {
414:         const scale = Math.max(w / im.width, h / im.height);
415:         const nw = im.width * scale, nh = im.height * scale;
416:         ctx.drawImage(im, x + (w - nw) / 2, y + (h - nh) / 2, nw, nh);
417:       } else {
418:         const grad = ctx.createLinearGradient(x, y, x + w, y + h);
419:         grad.addColorStop(0, "#1a2234");
420:         grad.addColorStop(1, "#0d111a");
421:         ctx.fillStyle = grad;
422:         ctx.fillRect(x, y, w, h);
423:       }
424:       ctx.restore();
425:     }
