    function drawDashedMirrorContour(x, y, w, h, accent) {
      ctx.save();
      const mx0 = x + w * 0.12, my0 = y + h * 0.22;
      const mx1 = x + w * 0.88, my1 = y + h * 0.84;
      ctx.beginPath();
      ctx.moveTo(mx0 + (mx1 - mx0) * 0.16, my0 + 8);
      ctx.lineTo(mx1 - 24, my0);
      ctx.quadraticCurveTo(mx1, my0, mx1, my0 + 26);
      ctx.lineTo(mx1 - 6, my1 - 24);
      ctx.quadraticCurveTo(mx1 - 18, my1, mx1 - 36, my1);
      ctx.lineTo(mx0 + 28, my1 - 12);
      ctx.quadraticCurveTo(mx0, my1 - 24, mx0, (my0 + my1) / 2);
      ctx.closePath();

      ctx.setLineDash([12, 7]);
      ctx.lineWidth = 6;
      ctx.strokeStyle = "#000";
      ctx.stroke();
      ctx.lineWidth = 3;
      ctx.strokeStyle = accent;
      ctx.stroke();
      ctx.setLineDash([]);

      // Draw 4-way outward expansion arrows (Left, Right, Up, Down) on the After mirror
      const cx = (mx0 + mx1) / 2, cy = (my0 + my1) / 2;
      function drawMiniArrow(ax, ay, dx, dy) {
        ctx.save();
        ctx.beginPath();
        if (dx !== 0) {
          ctx.moveTo(ax, ay - 7);
          ctx.lineTo(ax + dx * 8, ay - 7);
          ctx.lineTo(ax + dx * 8, ay - 14);
          ctx.lineTo(ax + dx * 20, ay);
          ctx.lineTo(ax + dx * 8, ay + 14);
          ctx.lineTo(ax + dx * 8, ay + 7);
          ctx.lineTo(ax, ay + 7);
        } else {
          ctx.moveTo(ax - 7, ay);
          ctx.lineTo(ax - 7, ay + dy * 8);
          ctx.lineTo(ax - 14, ay + dy * 8);
          ctx.lineTo(ax, ay + dy * 20);
          ctx.lineTo(ax + 14, ay + dy * 8);
          ctx.lineTo(ax + 7, ay + dy * 8);
          ctx.lineTo(ax + 7, ay);
        }
        ctx.closePath();
        ctx.lineWidth = 3;
        ctx.strokeStyle = "#000";
        ctx.stroke();
        ctx.fillStyle = accent;
        ctx.fill();
        ctx.restore();
      }
      drawMiniArrow(mx0 + 18, cy, -1, 0);
      drawMiniArrow(mx1 - 18, cy, 1, 0);
      drawMiniArrow(cx, my0 + 18, 0, -1);
      drawMiniArrow(cx, my1 - 18, 0, 1);
      ctx.restore();
    }

