    for t in data.get("tracks", []):
        ttype = t.get("type", "video")
        raw_name = (t.get("name") or "").strip()
        cnt = type_counts.get(ttype, 0)
        type_counts[ttype] = cnt + 1
        if raw_name and raw_name not in used_track_names:
            tname = raw_name
        else:
            cand = ttype if cnt == 0 else f"{ttype}_{cnt}"
            while cand in used_track_names:
                cnt += 1
                cand = f"{ttype}_{cnt}"
            tname = cand
        used_track_names.add(tname)

        tracks_out.append(
            {
                "name": tname,
                "type": ttype,
                "mute": bool(t.get("attribute", 0)),
                "relative_index": int(t.get("flag", 0)),
