            sid = s.get("id") or ""
            mid = s.get("material_id") or ""
            ttr = s.get("target_timerange") or {}
            str_ = s.get("source_timerange") or {}
            t_start = int(ttr.get("start", 0))
            t_dur = int(ttr.get("duration", 0))
            s_start = int(str_.get("start", 0))
            s_dur = int(str_.get("duration", t_dur))

            extra_refs = s.get("extra_material_refs") or []
            spd_val = float(s.get("speed", 1.0))
            tr_info = None
            seg_effects = []
            for ref_id in extra_refs:
                if ref_id in spd_map and spd_map[ref_id].get("speed"):
                    spd_val = float(spd_map[ref_id]["speed"])
                if ref_id in tr_map:
                    tm = tr_map[ref_id]
                    tr_info = {
                        "id": ref_id,
                        "name": tm.get("name", ""),
                        "effect_id": tm.get("effect_id", ""),
                        "resource_id": tm.get("resource_id", ""),
                        "duration_us": int(tm.get("duration", 0)),
                    }
                if ref_id in eff_map:
                    em = eff_map[ref_id]
                    seg_effects.append(
                        {
                            "id": ref_id,
                            "name": em.get("name", ""),
                            "type": em.get("type", ""),
                        }
                    )

            clip_cfg = s.get("clip") or {}
            scale_cfg = clip_cfg.get("scale") or {}
            trans_cfg = clip_cfg.get("transform") or {}
            flip_cfg = clip_cfg.get("flip") or {}
            clip_settings = {
                "alpha": float(clip_cfg.get("alpha", 1.0)),
                "rotation": float(clip_cfg.get("rotation", 0.0)),
                "scale_x": float(scale_cfg.get("x", 1.0)),
                "scale_y": float(scale_cfg.get("y", 1.0)),
                "transform_x": float(trans_cfg.get("x", 0.0)),
                "transform_y": float(trans_cfg.get("y", 0.0)),
                "flip_horizontal": bool(flip_cfg.get("horizontal", False)),
                "flip_vertical": bool(flip_cfg.get("vertical", False)),
            }

            seg_entry: Dict[str, Any] = {
                "id": sid,
                "kind": ttype,
                "track": tname,
                "material_id": mid,
                "target_start_us": t_start,
                "target_duration_us": t_dur,
                "source_start_us": s_start,
                "source_duration_us": s_dur,
                "speed": round(spd_val, 6),
                "volume": float(s.get("volume", 1.0)),
                "clip_settings": clip_settings,
            }
            if tr_info:
                seg_entry["transition"] = tr_info
            if seg_effects:
                seg_entry["effects"] = seg_effects

            if mid in vid_map:
                vm = vid_map[mid]
                seg_entry["path"] = vm.get("path", "")
                seg_entry["material_name"] = vm.get("material_name") or os.path.basename(vm.get("path", ""))
                seg_entry["width"] = int(vm.get("width", 0))
                seg_entry["height"] = int(vm.get("height", 0))
                seg_entry["material_duration_us"] = int(vm.get("duration", 0))
            elif mid in aud_map:
                am = aud_map[mid]
                seg_entry["path"] = am.get("path", "")
                seg_entry["material_name"] = am.get("name") or os.path.basename(am.get("path", ""))
                seg_entry["material_duration_us"] = int(am.get("duration", 0))
            elif mid in txt_map:
                tm = txt_map[mid]
                raw_c = tm.get("content", "")
                parsed_t = raw_c
                try:
                    parsed_t = json.loads(raw_c).get("text", raw_c)
                except Exception:
                    pass
                seg_entry["text"] = parsed_t
                seg_entry["font"] = tm.get("font_path") or tm.get("font_name") or ""
            elif mid in stk_map:
                sm = stk_map[mid]
                seg_entry["material_name"] = sm.get("name", "sticker")
            elif mid in eff_map:
                em = eff_map[mid]
                seg_entry["effect_type"] = em.get("name", "effect")

            segments_out.append(seg_entry)

    proj = {
        "schema": "cli-anything-capcut/v1",
        "name": os.path.basename(os.path.dirname(abs_path)) or "Imported Draft",
        "created_at": datetime.now(timezone.utc).isoformat(),
        "canvas": {
            "width": int(cc_canvas.get("width", 1920)),
            "height": int(cc_canvas.get("height", 1080)),
            "fps": int(data.get("fps", 30)),
            "maintrack_adsorb": bool(
                data.get("config", {}).get("maintrack_adsorb", True)
            ),
        },
        "tracks": tracks_out,
        "segments": segments_out,
        "srt_imports": [],
        "duration_us": int(data.get("duration", 0)),
        "native_draft_path": abs_path,
        "_dirty_segments": [],
        "_structure_dirty": False,
    }
    resolve_portable_project(proj, abs_path)
    invalidate_project_index(proj)
    if not proj["duration_us"]:
        recompute_duration(proj)
    return proj

