def list_segments(
    project: Dict[str, Any],
    track_name: Optional[str] = None,
    kind: Optional[str] = None,
    at_time: Optional[Any] = None,
    segment_id: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """List segments in the project, optionally filtered by track, kind, active timestamp (O(log N)), or ID/name (O(1))."""
    p_idx = get_project_index(project)
    active_ids: Optional[set] = None
    if at_time is not None:
        at_us = parse_time_us(at_time)
        active_ids = set()
        target_tracks = (
            [track_name] if track_name else list(p_idx.track_intervals.keys())
        )
        for trk in target_tracks:
            ivs = p_idx.track_intervals.get(trk, [])
            if not ivs:
                continue
            pos = bisect.bisect_right(ivs, (at_us, float("inf"), "\xff"))
            for i in range(max(0, pos - 4), min(len(ivs), pos + 1)):
                s_us, e_us, sid = ivs[i]
                if s_us <= at_us < e_us:
                    active_ids.add(sid)

    if segment_id and segment_id in p_idx.by_id:
        seg = p_idx.by_id[segment_id]
        if (not track_name or seg.get("track") == track_name) and (
            not kind or seg.get("kind") == kind
        ):
            item = deepcopy(seg)
            item["index"] = 0
            item["start_seconds"] = round(int(seg.get("target_start_us", 0)) / 1_000_000, 3)
            item["duration_seconds"] = round(
                int(seg.get("target_duration_us", 0)) / 1_000_000, 3
            )
            return [item]

    result: List[Dict[str, Any]] = []
    q_low = segment_id.lower() if segment_id else None
    for idx, seg in enumerate(project.get("segments", [])):
        if active_ids is not None and seg.get("id") not in active_ids:
            continue
        if track_name and seg.get("track") != track_name:
            continue
        if kind and seg.get("kind") != kind:
            continue
        if q_low:
            hay = " ".join(
                str(seg.get(k, ""))
                for k in ("id", "material_name", "text", "path")
            ).lower()
            if q_low not in hay:
                continue
        item = deepcopy(seg)
        item["index"] = idx
        item["start_seconds"] = round(int(seg.get("target_start_us", 0)) / 1_000_000, 3)
        item["duration_seconds"] = round(
            int(seg.get("target_duration_us", 0)) / 1_000_000, 3
        )
        result.append(item)
    return result

